const maxAvatarBytes = 1024 * 1024;
const avatarMimeTypes = ["image/jpeg", "image/png", "image/webp"];

export function ProfileSettings() {
  const [displayName, setDisplayName] = useState("Josue Admin");
  const [avatarUrl, setAvatarUrl] = useState<string | null>(null);
  const avatarInputRef = useRef<HTMLInputElement>(null);

  function selectAvatar(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    if (!avatarMimeTypes.includes(file.type)) {
      toast.error("Usa una imagen JPG, PNG o WebP.");
      return;
    }
    if (file.size > maxAvatarBytes) {
      toast.error("La imagen supera 1 MB.");
      return;
    }
    if (avatarUrl) URL.revokeObjectURL(avatarUrl);
    setAvatarUrl(URL.createObjectURL(file));
    toast.success("Foto de perfil actualizada.");
  }

  function removeAvatar() {
    if (avatarUrl) URL.revokeObjectURL(avatarUrl);
    setAvatarUrl(null);
    toast.success("Foto de perfil eliminada.");
  }

