    .select({ id: users.id })
    .from(users)
    .where(eq(sql`lower(${users.email})`, email))
    .limit(1);

  if (existingUser) {
    throw new AppException(
      'AUTH_EMAIL_ALREADY_REGISTERED',
      HttpStatus.CONFLICT,
    );
  }

