    .insert(users)
    .values({
      email,
      displayName: data.displayName,
      passwordHash,
      timezone: data.timezone,
      isPlatformAdmin: false,
    })
    .returning({
      id: users.id,
      email: users.email,
      displayName: users.displayName,
      locale: users.locale,
    });

