  constructor(private readonly database: DatabaseService) {}

  async getProfile(
    session: PlatformAdminAuthSession | PortalAuthSession,
  ): Promise<PortalProfile> {
    const user = await this.findUser(session.user.id);
    return this.toProfile(user);
  }

  async updateProfile(
    session: PlatformAdminAuthSession | PortalAuthSession,
    input: unknown,
  ): Promise<PortalProfile> {
    const parsed = updatePortalProfileSchema.safeParse(input);
    if (!parsed.success)
      throw new AppException('VALIDATION_FAILED', HttpStatus.BAD_REQUEST);

    if (parsed.data.locale) {
      const [language] = await this.database.db
        .select({ code: languages.code })
        .from(languages)
        .where(
          and(
            eq(languages.code, parsed.data.locale),
            eq(languages.isActive, true),
          ),
        )
        .limit(1);
      if (!language)
        throw new AppException('VALIDATION_FAILED', HttpStatus.BAD_REQUEST);
    }

    const [user] = await this.database.db
      .update(users)
      .set({
        displayName: parsed.data.displayName,
        locale: parsed.data.locale,
        timezone: parsed.data.timezone,
        updatedAt: new Date(),
      })
      .where(eq(users.id, session.user.id))
      .returning(this.profileSelection());

    if (!user)
      throw new AppException('AUTH_SESSION_EXPIRED', HttpStatus.UNAUTHORIZED);

    await this.database.db.insert(apiAuditLogs).values({
      workspaceId: session.area === 'portal' ? session.workspace.id : null,
      actorUserId: session.user.id,
      event: 'profile.updated',
      subjectType: 'user',
      subjectId: session.user.id,
      metadata: {
        changedFields: ['displayName', 'locale', 'timezone'],
      },
    });

    return this.toProfile(user);
  }

